    private static Set<CustomerStatus> parseStatuses(String raw) {
        if (raw == null || raw.isBlank()) {
            return Set.of();
        }
        Set<CustomerStatus> result = EnumSet.noneOf(CustomerStatus.class);
        for (String token : raw.split(",")) {
            if (token.isBlank()) {
                continue;
            }
            try {
                result.add(CustomerStatus.valueOf(token.trim()));
            } catch (IllegalArgumentException ignored) {
            }
        }
        return result;
    }
