+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * A filter over the customer data set, applied by {@link CustomerRepository}.
+ *
+ * <p>The name part is a list of terms, split from the user's input on
+ * whitespace. A customer matches when <em>every</em> term occurs as a
+ * substring of the first name or the last name. Matching is insensitive to
+ * case and to accents: {@code makinen}, {@code MAKINEN} and {@code mäkinen}
+ * all match {@code Makinen}. An empty name part matches every customer.
+ *
+ * <p>The status part is a set of {@link CustomerStatus} values. With an empty
+ * set every status is shown; with one or more values only customers with one
+ * of those statuses are shown.
+ */
+public record CustomerFilter(List<String> terms, Set<CustomerStatus> statuses) {
+
+    /** A filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter(List.of(), Set.of());
+
+    /**
+     * Builds a filter from raw user input.
+     *
+     * @param name     the name text, split on whitespace into terms; may be null
+     * @param statuses the selected statuses; may be null
+     */
+    public static CustomerFilter of(String name, Set<CustomerStatus> statuses) {
+        List<String> terms = Arrays.stream((name == null ? "" : name).trim().split("\\s+"))
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::normalize)
+                .toList();
+        Set<CustomerStatus> selected = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+        return new CustomerFilter(terms, selected);
+    }
+
+    /** Whether this filter matches every customer. */
+    public boolean isEmpty() {
+        return terms.isEmpty() && statuses.isEmpty();
+    }
+
+    /** Whether the given customer satisfies this filter. */
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /** Case- and accent-insensitive form of the given text. */
+    static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{InCombiningDiacriticalMarks}", "").toLowerCase(Locale.ROOT);
+    }
+}
