+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.customers.domain.QueryLog;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.junit.jupiter.api.AfterEach;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+/**
+ * Real-browser verification of the parts that only a browser can show: what
+ * the address bar says and what typing costs the backend. Named {@code *IT} so
+ * it is not part of the default browserless {@code mvn -o test} run; execute
+ * it explicitly with {@code mvn -o test -Dtest=CustomerListViewBrowserIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://[REDACTED]host:" + port;
+    }
+
+    @BeforeEach
+    void setUp() throws Exception {
+        queryLog.clear();
+        setupTest();
+    }
+
+    @AfterEach
+    void tearDown() {
+        cleanupTest();
+    }
+
+    private Locator summary(String text) {
+        return getPage().getByText(text, new Page.GetByTextOptions().setExact(true));
+    }
+
+    private void waitForUrlContains(String fragment) {
+        getPage().waitForFunction("url => window.location.href.includes(url)", fragment,
+                new Page.WaitForFunctionOptions().setTimeout(10_000));
+    }
+
+    @Test
+    void unfilteredViewHasNoFilterInTheUrl() {
+        summary("Showing 500 of 500").waitFor();
+        String url = getPage().url();
+        assertFalse(url.contains("name="), url);
+        assertFalse(url.contains("status="), url);
+
+        assertEquals("Filter by name",
+                getPage().locator("vaadin-text-field input").first().getAttribute("placeholder"));
+        getPage().locator("vaadin-multi-select-combo-box label").first()
+                .waitFor(new Locator.WaitForOptions().setTimeout(10_000));
+        assertEquals("Status",
+                getPage().locator("vaadin-multi-select-combo-box label").first().textContent());
+    }
+
+    @Test
+    void typingUpdatesTheSummaryTheUrlAndCostsFewQueries() {
+        summary("Showing 500 of 500").waitFor();
+        queryLog.clear();
+
+        Locator input = getPage().locator("vaadin-text-field input").first();
+        input.pressSequentially("josephine", new Locator.PressSequentiallyOptions().setDelay(20));
+
+        summary("Showing 12 of 500").waitFor(new Locator.WaitForOptions().setTimeout(10_000));
+        waitForUrlContains("name=josephine");
+        assertFalse(getPage().url().contains("status="), getPage().url());
+
+        // The nine keystrokes must have produced one debounced value change,
+        // i.e. at most a couple of backend queries, each still a bounded page.
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing a nine-letter name produced " + queryLog.pageQueries().size() + " page queries");
+        assertTrue(queryLog.rowsFetched() <= 200,
+                "Typing pulled " + queryLog.rowsFetched() + " rows over the page limit");
+        assertTrue(queryLog.countQueries().contains(12),
+                "The backend should have counted the 12 matches, saw " + queryLog.countQueries());
+    }
+
+    @Test
+    void theStatusFilterIsWrittenToTheUrlInDeclarationOrder() {
+        summary("Showing 500 of 500").waitFor();
+
+        getPage().locator("vaadin-multi-select-combo-box").first().click();
+        selectStatusItem("CLOSED");
+        selectStatusItem("ACTIVE");
+
+        summary("Showing 333 of 500").waitFor(new Locator.WaitForOptions().setTimeout(10_000));
+        // Both selected, listed in declaration order, with a literal comma.
+        waitForUrlContains("status=ACTIVE,CLOSED");
+    }
+
+    private void selectStatusItem(String status) {
+        getPage().locator("vaadin-multi-select-combo-box-item")
+                .filter(new Locator.FilterOptions().setHasText(status))
+                .first()
+                .click(new Locator.ClickOptions().setTimeout(10_000));
+    }
+
+    @Test
+    void openingAFilteredLinkAppliesTheFilter() {
+        getPage().navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        getPage().waitForLoadState();
+
+        summary("Showing 10 of 500").waitFor(new Locator.WaitForOptions().setTimeout(15_000));
+
+        assertEquals("vir", getPage().locator("vaadin-text-field input").first().inputValue());
+    }
+}
